package vn.rtr.aeris.mission;
import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
/** Administrative cold storage only. No input, network, flight or authority API.
 * Every original survives at exactly one source/archive path. Partial records
 * remain charged; only an explicit recover action can continue a pending batch. */
public final class JournalLifecycle17 {
 public static final long TOTAL=64L*1024*1024;public static final int ACTIVE=8,BATCHES=8,ROWS=8,ATTEMPTS=8;public static final String ARCHIVES="product-input-archives17";
 public static final byte[] MAGIC="AERIS_INPUT_JOURNAL_V2\n".getBytes(StandardCharsets.US_ASCII);
 public interface Sync{void directory(File f)throws IOException;}public interface Fault{void at(String point)throws IOException;}
 public static final class Entry{public final String generation,sha,disposition,proof;public final long bytes;Entry(String[] v)throws IOException{if(v.length!=6||!v[1].matches("[a-f0-9]{32}")||!v[3].matches("[a-f0-9]{64}")||!v[5].matches("[a-f0-9]{64}"))throw bad("PLAN_ROW");generation=v[1];try{bytes=Long.parseLong(v[2]);}catch(Exception e){throw bad("PLAN_BYTES");}if(bytes<MAGIC.length||bytes>32L*1024*1024)throw bad("PLAN_BYTES");sha=v[3];disposition=v[4];proof=v[5];if(!disposition.equals("UNUSED")&&!disposition.equals("CLOSED_VERIFIED"))throw bad("UNRESOLVED_ROTATION_REFUSED");}}
 public static final class Plan{public final byte[] raw;public final String sha,oldAPK,oldSource,newSource,backup,receiver,cold,expectedHead;public final long backupBytes;public final List<Entry> entries=new ArrayList<>();
  public Plan(byte[] b)throws IOException{if(b.length<200||b.length>16384)throw bad("PLAN16K");for(byte x:b)if(x<9||x>126||x==13)throw bad("PLAN_ASCII");String text=new String(b,StandardCharsets.US_ASCII);if(!text.endsWith("\n"))throw bad("PLAN_NEWLINE");String[] lines=text.split("\n",-1);if(lines.length<12||!lines[0].equals("AERIS_JOURNAL_LIFECYCLE17\t1")||!lines[1].equals("package\tvn.rtr.aeris.betasim09"))throw bad("PLAN_SCOPE");oldAPK=hash(lines[2],"oldAPK");oldSource=hash(lines[3],"oldSource");newSource=hash(lines[4],"newSource");String[] backupRow=lines[5].split("\t",-1);if(backupRow.length!=3||!backupRow[0].equals("backup")||!backupRow[1].matches("[a-f0-9]{64}"))throw bad("BACKUP_BINDING");backup=backupRow[1];try{backupBytes=Long.parseLong(backupRow[2]);}catch(Exception e){throw bad("BACKUP_BYTES");}if(backupBytes<1024||backupBytes>192L*1024*1024)throw bad("BACKUP_BYTES");receiver=hash(lines[6],"receiver");cold=hash(lines[7],"cold");String[] eh=lines[8].split("\t",-1);if(eh.length!=2||!eh[0].equals("expectedHead")||!(eh[1].equals("ROOT")||eh[1].matches("[a-f0-9]{64}")))throw bad("EXPECTED_HOST_HEAD");expectedHead=eh[1];Set<String> seen=new HashSet<>();int i=9;for(;i<lines.length&&!lines[i].equals("end");i++){String[] v=lines[i].split("\t",-1);if(v.length==0||!v[0].equals("generation"))throw bad("PLAN_ROW");Entry e=new Entry(v);if(!seen.add(e.generation)||entries.size()>=ROWS)throw bad("PLAN_UNIQUE_ROWS8");entries.add(e);}if(entries.isEmpty()||i!=lines.length-2||!lines[lines.length-1].isEmpty())throw bad("PLAN_END");raw=b.clone();sha=digest(b);}
  private static String hash(String row,String name)throws IOException{String[] v=row.split("\t",-1);if(v.length!=2||!v[0].equals(name)||!v[1].matches("[a-f0-9]{64}"))throw bad("PLAN_"+name);return v[1];}}
 public static final class Stats{public long totalBytes,records;public int active,archived,batches,pending;public final Set<String> generations=new HashSet<>();}
 private final File files;private final Sync sync;private final Fault fault;private final JournalGuard17.Boundary boundary;
 public JournalLifecycle17(File f,Sync s,Fault x)throws IOException{this(f,s,x,new JournalGuard17.Boundary());}
 public JournalLifecycle17(File f,Sync s,Fault x,JournalGuard17.Boundary b)throws IOException{boundary=b;files=f.getCanonicalFile();if(!files.equals(f.getAbsoluteFile())||!files.isDirectory())throw bad("FILES_ROOT");sync=s;fault=x;}
 private static IOException bad(String x){return new IOException("JOURNAL17_"+x);}public static String digest(byte[] b){try{byte[] h=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte x:h)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 private File child(File root,String name)throws IOException{File f=new File(root,name);if(!f.getCanonicalFile().equals(f.getAbsoluteFile()))throw bad("SYMLINK");if(f.exists()){JournalGuard17.Fact fact=boundary.fact(f);if(fact.regular&&fact.links!=1||!fact.regular&&!fact.directory)throw bad("SINGLE_LINK_OR_DIRECTORY");}return f;}
 private byte[] read(File f,int maximum)throws IOException{return boundary.read(f,maximum);}
 private List<File> list(File f)throws IOException{File[] xs=f.listFiles();if(xs==null)throw bad("DIRECTORY_LIST");Arrays.sort(xs,Comparator.comparing(File::getName));return Arrays.asList(xs);}
 private void mkdir(File f)throws IOException{fault.at("before_mkdir:"+f.getName());if(!f.mkdir())throw bad("EXCLUSIVE_DIRECTORY");fault.at("after_mkdir:"+f.getName());sync.directory(f.getParentFile());fault.at("after_dirsync:"+f.getName());}
 private byte[] commit(Plan p){return("AERIS_JOURNAL17_COMMITTED\t"+p.sha+"\t"+p.receiver+"\n").getBytes(StandardCharsets.US_ASCII);}
 private boolean has(File dir,String prefix,byte[] wanted)throws IOException{for(File f:list(dir))if(f.getName().matches(prefix+"-[0-7]\\.record")&&f.length()==wanted.length&&Arrays.equals(read(child(dir,f.getName()),16384),wanted))return true;return false;}
 private void durable(File dir,String prefix,byte[] b)throws IOException{for(int i=0;i<ATTEMPTS;i++){File f=child(dir,prefix+"-"+i+".record");if(f.exists())continue;fault.at("before_create:"+prefix);try(FileOutputStream out=boundary.exclusive(f)){fault.at("before_write:"+prefix);out.write(b);fault.at("after_write:"+prefix);out.getFD().sync();fault.at("after_filesync:"+prefix);}sync.directory(dir);fault.at("after_dirsync:"+prefix);return;}throw bad("RECOVERY_ATTEMPTS_FULL");}
 private void verify(File f,Entry e)throws IOException{byte[] raw=read(f,32*1024*1024);if(raw.length!=e.bytes||!digest(raw).equals(e.sha))throw bad("ORIGINAL_SHA");if(e.disposition.equals("UNUSED")){if(!Arrays.equals(raw,MAGIC))throw bad("UNUSED_NOT_EXACT_MAGIC");}else if(structuralRecords(raw)==0)throw bad("CLOSED_EMPTY_NOT_SUCCESS");}
 /** Strict structure only. CLOSED identity/signatures/closure must have an independent
  * original-STATUS/ACK receiver proof before this administrative plan is issued. */
 public static long structuralRecords(byte[] b)throws IOException{if(b.length<MAGIC.length||b.length>32*1024*1024||!Arrays.equals(Arrays.copyOf(b,MAGIC.length),MAGIC))throw bad("AJ02_MAGIC");int at=MAGIC.length;long seq=0,last=-1;String head=String.join("",Collections.nCopies(64,"0"));boolean pending=false;while(at<b.length){if(at+4>b.length)throw bad("AJ02_TORN");int n=ByteBuffer.wrap(b,at,4).getInt();if(n<82||n>2581||at+4+n>b.length)throw bad("AJ02_BOUND");byte[] body=Arrays.copyOfRange(b,at+4,at+4+n-32),h=Arrays.copyOfRange(b,at+4+n-32,at+4+n);ByteBuffer q=ByteBuffer.wrap(body);long number=q.getLong(),elapsed=q.getLong();int kind=q.get()&255;byte[] previous=new byte[32];q.get(previous);byte[] payload=new byte[q.remaining()];q.get(payload);StringBuilder prior=new StringBuilder();for(byte x:previous)prior.append(String.format(Locale.ROOT,"%02x",x&255));if(++seq>24576||number!=seq||elapsed<0||elapsed<last||!prior.toString().equals(head)||!digest(body).equals(hex(h)))throw bad("AJ02_CHAIN");if(kind==1&&!pending&&payload.length<=2500)pending=true;else if(kind==2&&pending&&new String(payload,StandardCharsets.US_ASCII).matches("[1-5][0-9]{2}"))pending=false;else throw bad("AJ02_PAIR_ORDER");head=hex(h);last=elapsed;at+=4+n;}if(pending)throw bad("AJ02_UNRESOLVED");return seq;}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}
 public synchronized Stats inspect(boolean allowPending)throws IOException{try(JournalGuard17.Scope scope=JournalGuard17.enter(files,boundary,sync,0)){return inspect(allowPending,true);}}
 public Stats accounting()throws IOException{try(JournalGuard17.Scope scope=JournalGuard17.enter(files,boundary,sync,0)){return inspect(true,false);}}
 private Stats inspect(boolean allowPending,boolean verifyOriginals)throws IOException{JournalGuard17.require(files);Stats s=new Stats();File active=child(files,"product-input01");if(active.exists()){if(!active.isDirectory())throw bad("ACTIVE_DIRECTORY");for(File f:list(active)){if(!f.getName().matches("[a-f0-9]{32}\\.aj02")||!f.isFile())throw bad("ACTIVE_ENTRY");child(active,f.getName());if(!s.generations.add(f.getName()))throw bad("DUPLICATE_GENERATION");s.active++;s.totalBytes+=f.length();if(verifyOriginals)s.records+=structuralRecords(read(f,32*1024*1024));}}if(s.active>ACTIVE)throw bad("ACTIVE8");File archives=child(files,ARCHIVES);if(archives.exists()){if(!archives.isDirectory())throw bad("ARCHIVE_DIRECTORY");for(File dir:list(archives)){if(!dir.getName().matches("[a-f0-9]{64}")||!dir.isDirectory()||++s.batches>BATCHES)throw bad("BATCHES8");child(archives,dir.getName());Plan p=null;int count=0;for(File f:list(dir)){child(dir,f.getName());if(!f.isFile()||++count>24)throw bad("BATCH_ENTRIES");s.totalBytes+=f.length();if(f.getName().matches("intent-[0-7]\\.record")&&f.length()<=16384){try{Plan candidate=new Plan(read(f,16384));if(candidate.sha.equals(dir.getName()))p=candidate;}catch(IOException ignored){}}if(f.getName().matches("[a-f0-9]{32}\\.aj02")){if(!s.generations.add(f.getName()))throw bad("DUPLICATE_GENERATION");s.archived++;}else if(!f.getName().matches("(intent|commit)-[0-7]\\.record"))throw bad("ARCHIVE_FOREIGN_ENTRY");}if(p==null||!has(dir,"commit",commit(p))){s.pending++;if(!allowPending)throw bad("PENDING_EXPLICIT_RECOVERY_REQUIRED");}else{for(Entry e:p.entries){File original=child(dir,e.generation+".aj02");if(!original.isFile()||original.length()!=e.bytes)throw bad("ARCHIVE_ORIGINAL_SIZE");if(verifyOriginals){verify(original,e);s.records+=structuralRecords(read(original,32*1024*1024));}}if(list(dir).stream().filter(f->f.getName().endsWith(".aj02")).count()!=p.entries.size())throw bad("ARCHIVE_ORIGINAL_SET");}}}File receipts=child(files,"product-input-lifecycle17");if(receipts.exists()){int count=0;for(File f:list(receipts)){child(receipts,f.getName());if(!f.isFile()||!(f.getName().equals("guard.lock")||f.getName().matches("request-[a-f0-9]{32}\\.json"))||++count>33||f.length()>4096)throw bad("RECEIPTS32");s.totalBytes+=f.length();}}s.totalBytes=boundary.inputBytes(files);if(s.archived>BATCHES*ROWS||s.totalBytes>TOTAL)throw bad("GLOBAL64MIB");return s;}
 public Stats preview(Plan p)throws IOException{try(JournalGuard17.Scope lock=JournalGuard17.enter(files,boundary,sync,(p.raw.length+512L)*ATTEMPTS+4096)){Stats stats=inspect(true);File active=child(files,"product-input01"),dir=child(child(files,ARCHIVES),p.sha);if(!active.isDirectory())throw bad("ACTIVE_REQUIRED");Set<String> expected=new HashSet<>();for(Entry e:p.entries)expected.add(e.generation+".aj02");for(File f:list(active))if(!expected.contains(f.getName()))throw bad("BACKUP_ACTIVE_SET_CHANGED");for(Entry e:p.entries){File old=child(active,e.generation+".aj02"),moved=child(dir,e.generation+".aj02");if(old.exists()==moved.exists())throw bad("EXACTLY_ONE_ORIGINAL_LOCATION");verify(old.exists()?old:moved,e);}if(stats.batches>=BATCHES&&!dir.exists())throw bad("BATCHES8_FULL_NO_DELETE");return stats;}}
 public synchronized String apply(Plan p,boolean recovery)throws IOException{try(JournalGuard17.Scope lock=JournalGuard17.enter(files,boundary,sync,(p.raw.length+512L)*ATTEMPTS+4096)){return applyLocked(p,recovery);}}
 private String applyLocked(Plan p,boolean recovery)throws IOException{JournalGuard17.require(files);JournalRegistry17 registry=new JournalRegistry17(files,sync,fault,boundary);java.util.List<JournalRegistry17.Original> originals=new java.util.ArrayList<>();for(Entry e:p.entries)originals.add(new JournalRegistry17.Original(e.generation,e.bytes,e.sha,e.disposition,e.proof));File active=child(files,"product-input01"),archives=child(files,ARCHIVES);Stats before=inspect(true);if(before.totalBytes+(p.raw.length+256L)*ATTEMPTS>TOTAL)throw bad("GLOBAL64MIB_RESERVE");if(!active.isDirectory())throw bad("ACTIVE_REQUIRED");File dir=child(archives,p.sha);if(dir.exists()&&has(dir,"commit",commit(p))){JournalRegistry17.Snapshot observed=registry.inspect(null,true);if(!observed.pending){inspect(false);return"ALREADY_COMMITTED_NO_REPLAY";}if(!recovery)throw bad("PENDING_EXPLICIT_RECOVERY_REQUIRED");}if(dir.exists()&&!recovery)throw bad("PENDING_EXPLICIT_RECOVERY_REQUIRED");if(!dir.exists()&&before.batches>=BATCHES)throw bad("BATCHES8_FULL_NO_DELETE");if(before.pending>(dir.exists()?1:0))throw bad("FOREIGN_PENDING_BATCH");Set<String> expected=new HashSet<>();for(Entry e:p.entries)expected.add(e.generation+".aj02");for(File f:list(active))if(!expected.contains(f.getName()))throw bad("BACKUP_ACTIVE_SET_CHANGED");for(Entry e:p.entries){File old=child(active,e.generation+".aj02"),moved=child(dir,e.generation+".aj02");if(old.exists()==moved.exists())throw bad("EXACTLY_ONE_ORIGINAL_LOCATION");verify(old.exists()?old:moved,e);}JournalRegistry17.Snapshot registryState=p.expectedHead.equals("ROOT")?registry.enroll(originals,p.backup,p.receiver,p.cold,"ROOT"):registry.inspect(p.expectedHead,true);JournalRegistry17.Ticket registryIntent=registry.beginArchive(p.sha,p.expectedHead.equals("ROOT")?registryState.head:p.expectedHead,originals);if(!archives.exists())mkdir(archives);if(!dir.exists())mkdir(dir);if(!has(dir,"intent",p.raw))durable(dir,"intent",p.raw);for(Entry e:p.entries){File old=child(active,e.generation+".aj02"),moved=child(dir,e.generation+".aj02");if(old.exists()){fault.at("before_rename:"+e.generation);JournalGuard17.Fact identity=boundary.fact(old);boundary.regular(old);if(moved.exists()||!old.renameTo(moved))throw bad("ORIGINAL_RENAME");if(!identity.same(boundary.fact(moved)))throw bad("MOVED_INODE_IDENTITY");fault.at("after_rename:"+e.generation);sync.directory(active);fault.at("after_source_dirsync:"+e.generation);sync.directory(dir);fault.at("after_archive_dirsync:"+e.generation);}verify(moved,e);}if(!has(dir,"commit",commit(p)))durable(dir,"commit",commit(p));registry.commitArchive(registryIntent,ARCHIVES+"/"+p.sha);inspect(false);return"ARCHIVED_VERIFIED_NO_AUTHORITY";}
 public synchronized void reserve(long additional)throws IOException{JournalGuard17.require(files);boundary.capacity(files,additional);Stats s=inspect(false,false);if(additional<0||s.totalBytes+additional>TOTAL)throw bad("GLOBAL64MIB");}
}
